 if(shape==='hoodie')body+='<path d="M74 28Q62 0 100 3 138 0 126 28L116 49 84 49Z" fill="url(#light)"/><path d="M85 45V93M115 45V93M77 124H123L132 151H68Z" fill="none" stroke="#fff" stroke-opacity=".3" stroke-width="2"/>';
